(function(){
  'use strict';
  var old=document.getElementById('printBtn'),sheet=document.getElementById('sheet');
  if(!old||!sheet||old.dataset.welogSaveFixed)return;
  var btn=old.cloneNode(true);btn.dataset.welogSaveFixed='1';old.parentNode.replaceChild(btn,old);
  function waitImages(root){var imgs=Array.from(root.querySelectorAll('img'));return Promise.all(imgs.map(function(img){if(img.complete&&img.naturalWidth)return Promise.resolve();return new Promise(function(resolve){var done=function(){resolve()};img.addEventListener('load',done,{once:true});img.addEventListener('error',done,{once:true});setTimeout(done,3000)})}))}
  function pairName(){try{var s=JSON.parse(localStorage.getItem('welog-pair-sheet-v4')||'{}');return((s.pairName||'WeLog').trim()||'WeLog')}catch(e){return'WeLog'}}
  function makeClone(){var c=sheet.cloneNode(true);c.removeAttribute('id');c.classList.add('welog-exact-preview-sheet','welog-save-sheet');c.querySelectorAll('.welog-layout-overlay').forEach(function(x){x.remove()});c.style.setProperty('transform','none','important');c.style.setProperty('margin','0','important');c.style.setProperty('box-shadow','none','important');c.style.setProperty('width',sheet.offsetWidth+'px','important');c.style.setProperty('height',sheet.offsetHeight+'px','important');c.style.setProperty('min-height','0','important');return c}
  function downloadCanvas(canvas){return new Promise(function(resolve,reject){if(canvas.toBlob){canvas.toBlob(function(blob){if(!blob){reject(new Error('PNG blob creation failed'));return}var url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=pairName()+'.png';document.body.appendChild(a);a.click();a.remove();setTimeout(function(){URL.revokeObjectURL(url)},1500);resolve()},'image/png');return}try{var a=document.createElement('a');a.download=pairName()+'.png';a.href=canvas.toDataURL('image/png');document.body.appendChild(a);a.click();a.remove();resolve()}catch(e){reject(e)}})}
  async function save(){if(!window.html2canvas)throw new Error('html2canvas unavailable');btn.disabled=true;btn.textContent='저장 중…';var host=document.createElement('div');host.className='welog-export-host';host.style.cssText='position:fixed!important;left:-20000px!important;top:0!important;display:block!important;visibility:visible!important;opacity:1!important;pointer-events:none!important;z-index:1!important;background:#fff!important;';var clone=makeClone();host.appendChild(clone);document.body.appendChild(host);try{await waitImages(clone);if(document.fonts&&document.fonts.ready)await document.fonts.ready;await new Promise(function(r){requestAnimationFrame(function(){requestAnimationFrame(r)})});var w=Math.max(1,clone.offsetWidth),h=Math.max(1,clone.offsetHeight);var canvas=await html2canvas(clone,{scale:2,useCORS:true,allowTaint:false,backgroundColor:'#ffffff',logging:false,imageTimeout:15000,width:w,height:h,windowWidth:w,windowHeight:h,scrollX:0,scrollY:0});await downloadCanvas(canvas)}finally{host.remove();btn.disabled=false;btn.textContent='↓ PNG 저장'}}
  btn.addEventListener('click',function(e){e.preventDefault();e.stopPropagation();save().catch(function(err){console.error('WeLog PNG export failed',err);alert('PNG 저장에 실패했습니다. 잠시 후 다시 시도해 주세요.')})});
})();